# packages
library(tidyverse)
library(NicheMapR)
library(kableExtra)
library(viridis)

# options
options(
  dplyr.summarise.inform = FALSE,
  knitr.table.html.attr = "quarto-disable-processing=true"
)




Code
microclimate_temps &lt;- readRDS("data/microclimate_temps.rds")

# define temperature thresholds
lethal &lt;- 0
ctmin &lt;- 5.4
retreat &lt;- 6.6

# define thresholds
thresholds &lt;- microclimate_temps |&gt;
  filter(z == 1.8) |&gt;
  mutate(
    thresh = case_when(
      min_annual_tb &lt; lethal ~ "lethal",
      min_annual_tb &gt;= lethal & min_annual_tb &lt; ctmin ~ "ctmin",
      min_annual_tb &gt;= ctmin & min_annual_tb &lt; retreat ~ "retreat",
      TRUE ~ "rest"
    )
  ) |&gt;
  select(lon, lat, thresh)

# merge microclimate temps with thresholds
microclimate_temps &lt;- merge(
  microclimate_temps,
  thresholds,
  by = c("lon", "lat"),
  all.x = TRUE
)

# define conditions to test
threshold_names &lt;- unique(microclimate_temps$thresh)
veg &lt;- seq(0, 1, by = 0.01)
heights &lt;- unique(microclimate_temps$z)

# create grid to store values
tss_grid &lt;- expand.grid(
  thresh = threshold_names,
  veg = veg,
  z = heights
)
tss_grid$tss &lt;- NA_real_

# loop through thresholds, tree covers, and heights to calculate TSS
for (i in seq_len(nrow(tss_grid))) {

  # add progress tracker
  cat("Processing row", i, "of", nrow(tss_grid), "\n")

  if (tss_grid$thresh[i] == "lethal") {
    data_subset &lt;- microclimate_temps |&gt;
      filter(
        thresh == "lethal",
        z == tss_grid$z[i]
      )
  } else if (tss_grid$thresh[i] == "ctmin") {
    data_subset &lt;- microclimate_temps |&gt;
      filter(
        thresh %in% c("lethal", "ctmin"),
        z == tss_grid$z[i]
      )
  } else if (tss_grid$thresh[i] == "retreat") {
    data_subset &lt;- microclimate_temps |&gt;
      filter(
        thresh != "rest",
        z == tss_grid$z[i]
      )
  } else {
    data_subset &lt;- microclimate_temps |&gt;
      filter(
        z == tss_grid$z[i]
      )
  }

  tss_value &lt;- data_subset |&gt;
    mutate(
      pred = min_annual_tb &gt; lethal & veg &gt; tss_grid$veg[i]
    ) |&gt;
    summarise(
      tp = sum(pred & presence),
      fp = sum(pred & !presence),
      fn = sum(!pred & presence),
      tn = sum(!pred & !presence)
    ) |&gt;
    mutate(tss = (tp / (tp + fn)) + (tn / (tn + fp)) - 1) |&gt;
    pull(tss)
  tss_grid$tss[i] &lt;- tss_value

}

# save tss grid
saveRDS(tss_grid, "data/tss_grid.rds")




