tss_grid &lt;- readRDS("data/tss_grid.rds")

# refactor threshold names for plotting
tss_grid$thresh &lt;- factor(
  tss_grid$thresh,
  levels = c("lethal", "ctmin", "retreat", "rest")
)

ggplot() +
  geom_tile(
    data = tss_grid,
    aes(x = veg, y = as.factor(z), fill = tss)
  ) +
  geom_point(
    data = tss_grid |&gt;
      group_by(thresh) |&gt;
      filter(tss == max(tss, na.rm = TRUE)) |&gt;
      ungroup(),
    aes(x = veg, y = as.factor(z)),
    color = "red",
    size = 3,
    shape = 1
  ) +
  geom_hline(
    yintercept = 20.5, color = "white", linetype = "solid"
  ) +
  geom_hline(
    yintercept = 22, color = "white", linetype = "dashed"
  ) +
  scale_fill_viridis_b(
    name = "TSS",
    limits = c(
      min(tss_grid$tss, na.rm = TRUE), max(tss_grid$tss, na.rm = TRUE)
    ),
    breaks = seq(
      min(tss_grid$tss, na.rm = TRUE), max(tss_grid$tss, na.rm = TRUE),
      by = 0.05
    ),
    # only show labels for every other break
    labels = function(x) ifelse(seq_along(x) %% 2 == 1, x, ""),
    guide = guide_colorsteps(
      barheight = unit(8, "cm"),
      barwidth = unit(0.5, "cm")
    )
  ) +
  scale_x_continuous(
    breaks = seq(0, 1, by = 0.2),
    labels = scales::percent_format(accuracy = 1),
    expand = c(0, 0)
  ) +
  scale_y_discrete(
    breaks = unique(tss_grid$z),
    expand = c(0, 0)
  ) +
  facet_wrap(
    vars(thresh),
    ncol = 4,
    axes = "all",
    labeller = labeller(
      thresh = as_labeller(
        c(
          lethal = "atop('Hard Physiological', 'Threshold (' * 0 * degree * 'C)')", # nolint
          ctmin = "atop('Soft Physiological', 'Threshold (' * CT[min] * ')')",
          retreat = "atop('Behavioral', 'Threshold (' * T[retreat] * ')')",
          rest = "atop('Rest of', 'Range')"
        ),
        label_parsed
      )
    )
  ) +
  labs(
    x = "Vegetation Cover",
    y = "Distance from surface\nabove or below leaf litter (m)"
  ) +
  theme_minimal() +
  theme(
    legend.position = "right",
    strip.text = element_text(size = 14),
    panel.border = element_rect(color = "black", fill = NA, linewidth = 0.5),
    axis.ticks = element_line(color = "black", linewidth = 0.25),
    axis.title = element_text(size = 12, lineheight = 1.25),
  )
